+// Sites: kitchens that share items, suppliers, recipes and dishes but keep
+// their own locations, and so their own batches and stock (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+/** The site a request without `X-Larder-Site` belongs to. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location belongs to, or undefined for an unknown location. */
+export function siteOfLocation(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site;
+}
+
+/** True when `batch` is stored at `site` (always true when `site` is undefined). */
+export function inSite(store, batch, site) {
+  return site === undefined || siteOfLocation(store, batch.location) === site;
+}
